mapper.select:
SELECT c.id, c.code, c.name, c.teacher_id, t.real_name AS teacherName, c.credit, c.semester, c.capacity, c.description, c.status, c.create_time, c.update_time FROM course c LEFT JOIN sys_user t ON c.teacher_id = t.id AND t.role = 'teacher'
AND (c.name LIKE CONCAT('%', #{courseQueryDTO.keyword}, '%') OR c.code LIKE CONCAT('%', #{courseQueryDTO.keyword}, '%'))
AND c.code = #{courseQueryDTO.code}
AND c.teacher_id = #{courseQueryDTO.teacherId}
AND c.semester = #{courseQueryDTO.semester}
AND c.status = #{courseQueryDTO.status}
ORDER BY c.create_time DESC

SELECT *
FROM course_schedule
WHERE day = #{day}
  AND lesson = #{lesson}
  AND (teacher_id = #{teacherId}
    OR class_id = #{classId}
    OR room = #{room})

    AND id != #{id}

mapper.insert:
INSERT INTO course_schedule (
    course_id, teacher_id, class_id, week, day, lesson, room, color, status, create_time, update_time
) VALUES (
             #{courseId}, #{teacherId}, #{classId}, #{week}, #{day}, #{lesson}, #{room}, #{color}, 1, NOW(), NOW()
         );

mapper.select:
SELECT cs.day, cs.lesson, cs.week AS weekJson, c.name AS courseName, tu.real_name AS teacherName, cl.name AS className, cs.room FROM course_schedule cs LEFT JOIN course c ON cs.course_id = c.id LEFT JOIN sys_user tu ON cs.teacher_id = tu.id LEFT JOIN org_class cl ON cs.class_id = cl.id
cs.course_id = #{courseId}
ORDER BY cs.day, cs.lesson
